<div class="container">

<!-- ═══ SECTION 1: Dataset Overview ═══ -->
<div class="section">
    <h2>1. Dataset Overview &amp; Coverage Summary</h2>
    <p>This analysis is based on government-mandated open fuel price data collected from UK forecourts. Each record represents a single price observation at a specific station and point in time.</p>

    <div class="kpi-row">
        {kpi_card('Total Records', f'{total_records:,}', color=COLORS['primary'])}
        {kpi_card('Unique Stations', f'{unique_stations:,}', color=COLORS['secondary'])}
        {kpi_card('Fuel Types', str(len(fuel_types)), ', '.join(sorted(fuel_types)), color=COLORS['success'])}
        {kpi_card('Date Range', f'{(date_range_end - date_range_start).days} days', f'{date_range_start.strftime("%d %b")} – {date_range_end.strftime("%d %b %Y")}', color=COLORS['warning'])}
    </div>

    <h3>Records by Fuel Type</h3>
    <table>
        <tr><th>Fuel Type</th><th>Records</th><th>Share of Data</th><th>Description</th></tr>
        {''.join(f'<tr><td><span class="fuel-badge" style="background:{get_fuel_color(ft)}">{ft}</span></td><td>{fuel_type_counts[ft]:,}</td><td>{fuel_type_counts[ft]/total_records*100:.1f}%</td><td>{{"E10":"Standard unleaded petrol","B7_STANDARD":"Standard diesel","E5":"Super unleaded petrol","B7_PREMIUM":"Premium diesel","B10":"B10 biodiesel","SDV":"Special diesel variant"}.get(ft,"—")}</td></tr>' for ft in fuel_type_counts.index)}
