print(f"Unique stations: {unique_stations:,}")
print(f"Fuel types: {', '.join(sorted(fuel_types))}")

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
import io
import warnings
warnings.filterwarnings('ignore')

# ─── Load Data ───
df = pd.read_csv('/app/benchmark/data.csv')
df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# ─── Color palette ───
COLORS = {
    'primary': '#1a365d',
    'secondary': '#2b6cb0',
    'accent': '#e53e3e',
    'bg': '#f7fafc',
    'card': '#ffffff',
    'text': '#1a202c',
    'muted': '#718096',
    'border': '#e2e8f0',
    'success': '#38a169',
    'warning': '#d69e2e',
}

FUEL_COLORS = {
    'E10': '#2b6cb0',
    'B7_STANDARD': '#e53e3e',
    'E5': '#38a169',
    'B7_PREMIUM': '#d69e2e',
    'B10': '#805ad5',
    'SDV': '#dd6b20',
}

def get_fuel_color(ft):
    return FUEL_COLORS.get(ft, '#718096')

def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

def fmt_pence(val):
    """Format pence as £X.XX/l"""
    return f"£{val/100:.2f}"

# ─── SECTION 1: Dataset Overview ───
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = df['fuel_type'].unique()
fuel_type_counts = df['fuel_type'].value_counts()
date_range_start = df['source_updated_at'].min()
date_range_end = df['source_updated_at'].max()
null_counts = df.isnull().sum()

# ─── SECTION 2: Price Distribution by Fuel Type ───
price_stats = df.groupby('fuel_type')['price_pence'].agg(
    count='count',
    mean='mean',
    median='median',
    std='std',
    min='min',
    max='max',
    q25=lambda x: x.quantile(0.25),
    q75=lambda x: x.quantile(0.75),
).sort_values('count', ascending=False)

# Box plot
fig, ax = plt.subplots(figsize=(10, 6))
fuel_order = price_stats.index.tolist()
box_data = [df[df['fuel_type'] == ft]['price_pence'].values for ft in fuel_order]
bp = ax.boxplot(box_data, labels=fuel_order, patch_artist=True, showfliers=True,
                flierprops=dict(marker='o', markersize=2, alpha=0.3))
for i, ft in enumerate(fuel_order):
    bp['boxes'][i].set_facecolor(get_fuel_color(ft))
    bp['boxes'][i].set_alpha(0.7)
    bp['medians'][i].set_color('black')
    bp['medians'][i].set_linewidth(2)
ax.set_ylabel('Price (pence per litre)', fontsize=12)
ax.set_xlabel('Fuel Type', fontsize=12)
ax.set_title('Price Distribution by Fuel Type', fontsize=14, fontweight='bold', color=COLORS['primary'])
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:.0f}p'))
ax.grid(axis='y', alpha=0.3)
plt.tight_layout()
boxplot_b64 = fig_to_base64(fig)

# Violin plot for top 3 fuel types by count
top3 = fuel_order[:3]
fig, ax = plt.subplots(figsize=(10, 6))
violin_data = [df[df['fuel_type'] == ft]['price_pence'].values for ft in top3]
parts = ax.violinplot(violin_data, positions=range(len(top3)), showmeans=True, showmedians=True)
for i, pc in enumerate(parts['bodies']):
    pc.set_facecolor(get_fuel_color(top3[i]))
    pc.set_alpha(0.7)
parts['cmeans'].set_color(COLORS['accent'])
parts['cmedians'].set_color('black')
ax.set_xticks(range(len(top3)))
ax.set_xticklabels(top3)
ax.set_ylabel('Price (pence per litre)', fontsize=12)
ax.set_title('Price Density — Top 3 Fuel Types', fontsize=14, fontweight='bold', color=COLORS['primary'])
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:.0f}p'))
ax.grid(axis='y', alpha=0.3)
plt.tight_layout()
violin_b64 = fig_to_base64(fig)

# Histogram for top 3
fig, axes = plt.subplots(1, 3, figsize=(14, 5), sharey=True)
for i, ft in enumerate(top3):
    data = df[df['fuel_type'] == ft]['price_pence']
    axes[i].hist(data, bins=40, color=get_fuel_color(ft), alpha=0.7, edgecolor='white')
    axes[i].axvline(data.mean(), color=COLORS['accent'], linestyle='--', linewidth=2, label=f'Mean: {data.mean():.1f}p')
    axes[i].axvline(data.median(), color='black', linestyle='-', linewidth=2, label=f'Median: {data.median():.1f}p')
    axes[i].set_title(ft, fontsize=13, fontweight='bold')
    axes[i].set_xlabel('Price (p/l)')
    axes[i].legend(fontsize=8)
    axes[i].grid(axis='y', alpha=0.3)
axes[0].set_ylabel('Frequency', fontsize=12)
fig.suptitle('Price Histograms — Top 3 Fuel Types', fontsize=14, fontweight='bold', color=COLORS['primary'], y=1.02)
plt.tight_layout()
hist_b64 = fig_to_base64(fig)

# ─── SECTION 3: Price Spread & Market Competitiveness ───
price_stats['range'] = price_stats['max'] - price_stats['min']
price_stats['iqr'] = price_stats['q75'] - price_stats['q25']

# Spread bar chart
fig, axes = plt.subplots(1, 2, figsize=(12, 5))

# Range chart
ax = axes[0]
y_pos = range(len(fuel_order))
bars = ax.barh(y_pos, price_stats.loc[fuel_order, 'range'], color=[get_fuel_color(ft) for ft in fuel_order], alpha=0.8)
ax.set_yticks(y_pos)
ax.set_yticklabels(fuel_order)
ax.set_xlabel('Price Range (p/l)', fontsize=11)
ax.set_title('Max − Min Price Spread', fontsize=13, fontweight='bold', color=COLORS['primary'])
for i, (v, ft) in enumerate(zip(price_stats.loc[fuel_order, 'range'], fuel_order)):
    ax.text(v + 0.5, i, f'{v:.1f}p', va='center', fontsize=10, fontweight='bold')
ax.grid(axis='x', alpha=0.3)

# IQR chart
ax = axes[1]
bars = ax.barh(y_pos, price_stats.loc[fuel_order, 'iqr'], color=[get_fuel_color(ft) for ft in fuel_order], alpha=0.8)
ax.set_yticks(y_pos)
ax.set_yticklabels(fuel_order)
ax.set_xlabel('Interquartile Range (p/l)', fontsize=11)
ax.set_title('IQR (25th–75th Percentile)', fontsize=13, fontweight='bold', color=COLORS['primary'])
for i, (v, ft) in enumerate(zip(price_stats.loc[fuel_order, 'iqr'], fuel_order)):
    ax.text(v + 0.2, i, f'{v:.1f}p', va='center', fontsize=10, fontweight='bold')
ax.grid(axis='x', alpha=0.3)

plt.tight_layout()
spread_b64 = fig_to_base64(fig)

# ─── SECTION 4: Update Freshness ───
lag_stats = df.groupby('fuel_type')['update_lag_hours'].agg(
    count='count',
    mean='mean',
    median='median',
    std='std',
    max='max',
    pct_over_24=lambda x: (x > 24).mean() * 100,
    pct_over_72=lambda x: (x > 72).mean() * 100,
).sort_values('count', ascending=False)

overall_median_lag = df['update_lag_hours'].median()
overall_mean_lag = df['update_lag_hours'].mean()
pct_over_24 = (df['update_lag_hours'] > 24).mean() * 100
pct_over_72 = (df['update_lag_hours'] > 72).mean() * 100

# Lag distribution histogram
fig, ax = plt.subplots(figsize=(10, 6))
lag_clipped = df['update_lag_hours'].clip(upper=df['update_lag_hours'].quantile(0.95))
for ft in top3:
    subset = lag_clipped[df['fuel_type'] == ft]
    ax.hist(subset, bins=50, alpha=0.5, color=get_fuel_color(ft), label=ft, edgecolor='white')
ax.axvline(overall_median_lag, color=COLORS['accent'], linestyle='--', linewidth=2, label=f'Overall Median: {overall_median_lag:.1f}h')
ax.set_xlabel('Update Lag (hours)', fontsize=12)
ax.set_ylabel('Frequency', fontsize=12)
ax.set_title('Distribution of Update Lag (Top 3 Fuel Types)', fontsize=14, fontweight='bold', color=COLORS['primary'])
ax.legend()
ax.grid(axis='y', alpha=0.3)
plt.tight_layout()
lag_hist_b64 = fig_to_base64(fig)

# Lag by fuel type box
fig, ax = plt.subplots(figsize=(10, 6))
lag_by_ft = [df[df['fuel_type'] == ft]['update_lag_hours'].clip(upper=72).values for ft in fuel_order]
bp = ax.boxplot(lag_by_ft, labels=fuel_order, patch_artist=True, showfliers=False)
for i, ft in enumerate(fuel_order):
    bp['boxes'][i].set_facecolor(get_fuel_color(ft))
    bp['boxes'][i].set_alpha(0.7)
    bp['medians'][i].set_color('black')
    bp['medians'][i].set_linewidth(2)
ax.set_ylabel('Update Lag (hours, capped at 72)', fontsize=11)
ax.set_title('Update Lag by Fuel Type', fontsize=14, fontweight='bold', color=COLORS['primary'])
ax.grid(axis='y', alpha=0.3)
plt.tight_layout()
lag_box_b64 = fig_to_base64(fig)

# Stale stations analysis
station_max_lag = df.groupby('node_id')['update_lag_hours'].max()
stale_threshold = 72  # hours
stale_stations = (station_max_lag > stale_threshold).sum()
